INSERT INTO public.articles (title, slug, excerpt, content, category, author_name, author_email, is_published, published_at)
VALUES (
  'Scheduled System Maintenance: 8 – 11 May 2026',
  'scheduled-maintenance-may-2026',
  'The LakeCity Customer Portal will be undergoing planned maintenance from Friday 8 May through Monday 11 May 2026.',
  E'Dear Valued Account Holder,\n\nWe are writing to let you know that the **LakeCity Customer Portal** will be undergoing scheduled maintenance from **Friday, 8 May 2026** through **Monday, 11 May 2026** as we roll out important upgrades to our systems.\n\n## What to expect\n\nDuring this window, the following services may be **temporarily unavailable or intermittent**:\n\n- Logging in to your account\n- Viewing your dashboard, statements, and payment history\n- Making payments through the portal\n- Receipt uploads and approvals\n- Two-factor authentication (2FA) codes\n\n## Why we are doing this\n\nThese upgrades are part of our ongoing commitment to **Honesty, Integrity, and Transparency** — strengthening the security, reliability, and performance of the platform you rely on to manage your stand.\n\n## When you can expect service to resume\n\nFull service is expected to be restored by **end of day Monday, 11 May 2026**. We will publish an update on the portal as soon as everything is back online.\n\n## Need help during this period?\n\nIf you have an urgent query, please contact our support team at **info@lakecity.co.zw** and we will respond as soon as possible.\n\nWe sincerely apologise for any inconvenience this may cause and thank you for your patience and continued trust.\n\nKind regards,\n\nLakeCity Tech',
  'announcement',
  'LakeCity Tech',
  'info@lakecity.co.zw',
  true,
  now()
);